$('pitch').oninput=()=>{const value=Number($('pitch').value);window.flightView?.setCamera?.({pitch:value});if(state.status==='photo')state.photoPitch=value;updatePhotoCameraReadout()};$('pitch').onchange=()=>log('camera_pitch','调整云台',$('pitch').value);function setPhotoFocalLength(value,final=false){if(state.status!=='photo')return;const focalLength=Math.max(8,Math.min(55,Number(value)||18)),pose=window.flightView?.setCamera?.({focalLength,final,source:'focal'},true);state.photoFocalLength=pose?.focalLength||focalLength;updatePhotoCameraReadout();if(final)log('camera_focal_length','调整拍照焦距',Math.round(state.photoFocalLength)+' mm')}$('photoFocalLength').addEventListener('input',e=>setPhotoFocalLength(e.currentTarget.value));$('photoFocalLength').addEventListener('change',e=>setPhotoFocalLength(e.currentTarget.value,true));function adjustPhotoCamera(yaw=0,pitch=0){if(state.status!=='photo')return;const pose=window.flightView?.nudgeCamera?.(yaw,pitch);if(pose){state.photoCameraYawOffset=pose.yawOffset;state.photoPitch=pose.pitch}updatePhotoCameraReadout()}document.querySelectorAll('[data-camera-yaw],[data-camera-pitch]').forEach(button=>button.onclick=()=>adjustPhotoCamera(Number(button.dataset.cameraYaw||0),Number(button.dataset.cameraPitch||0)));document.querySelectorAll('[data-camera-focal]').forEach(button=>button.onclick=()=>setPhotoFocalLength((state.photoFocalLength||18)+Number(button.dataset.cameraFocal||0),true));$('resetPhotoCamera').onclick=()=>{if(state.status!=='photo')return;alignPhotoCamera();toast('已恢复'+photoTargetName()+'推荐构图')};window.addEventListener('uav-camera-change',e=>{if(state.status!=='photo')return;state.photoCameraYawOffset=e.detail.yawOffset;state.photoPitch=e.detail.pitch;state.photoFocalLength=e.detail.focalLength||state.photoFocalLength;updatePhotoCameraReadout();if(e.detail.final)log('photo_camera_adjust','调整拍照构图',JSON.stringify({yawOffset:Math.round(e.detail.yawOffset*10)/10,pitch:Math.round(e.detail.pitch*10)/10,focalLength:Math.round((e.detail.focalLength||18)*10)/10,source:e.detail.source}))});function captureView(filename='uav-simulated-view.png',label='保存模拟视角'){try{if(!window.flightView)throw Error();const a=document.createElement('a');a.href=flightView.capture();a.download=filename;a.click();log('capture',label,filename);return true}catch{toast('当前设备无法保存视角');return false}}$('capture').onclick=()=>captureView();$('photoCheckin').onclick=()=>{const task=activePhotoTask();if(state.status!=='photo'||!task||Date.now()<(state.photoAligningUntil||0))return;const before=snap(),fileLabel=task.shortName||task.name,camera=window.flightView?.getCamera?.()||{yawOffset:state.photoCameraYawOffset||0,pitch:state.photoPitch,focalLength:state.photoFocalLength||18};if(!captureView('N1-'+fileLabel+'.png','保存任务打卡照片'))return;const evidence={checkpointId:task.id,checkpointName:task.name,capturedAt:new Date().toISOString(),simTime:state.simTime,heading:state.photoHeading,camera,target:state.photoLookAt};state.photoEvidence=Array.isArray(state.photoEvidence)?state.photoEvidence:[];state.photoEvidence.push(evidence);if(!completedPhotoIds().includes(task.id))completedPhotoIds().push(task.id);state.activePhotoCheckpointId=null;state.status='running';state.photoHeading=null;state.photoLookAt=null;state.photoCameraYawOffset=0;state.photoFocalLength=18;state.photoAligningUntil=0;window.flightView?.setCamera?.({yawOffset:0,focalLength:18});const remaining=photoTasks().length-completedPhotoIds().length;mission.title=remaining?fileLabel+'完成，继续前往下一个打卡点':'全部拍照打卡点均已完成，继续前往 B';mission.summary=remaining?'影像、镜头角度、焦距和任务时刻已保存，AI 已恢复航迹跟随；本航段还剩 '+remaining+' 个打卡点。':'全部影像、镜头角度及焦距均已保存并记录，AI 已恢复航迹跟随。';log('photo_checkin','完成'+task.name,JSON.stringify(evidence),before);toast(fileLabel+'完成，继续沿航线飞行');render()};
