function setAltitude(value){if(state.landing||state.landed||['editing','collision'].includes(state.status))return;const before=snap();state.targetAltitude=Math.max(0,Math.min(150,Math.round(Number(value)*10)/10));log('altitude_command','调整飞行高度','目标 '+state.targetAltitude+' m',before);$('pause').disabled=false;telemetry()}
