 if(next.done){state.altitude=plan.targetAltitude;state.targetAltitude=state.altitude;state.verticalSpeed=0;state.landed=true;state.landing=null;state.status='complete';mission.title=state.goalDeferred?'已返航并安全着陆':'已在目标点安全着陆';mission.summary='下降完成，无人机已着陆，本次低电量任务结束。';log('landing_complete','完成着陆',JSON.stringify(plan));log('complete','任务结束',state.goalDeferred?'已返航并着陆，原目标暂缓':'已在 '+mission.destination.name+' 着陆');render()}
