async function prepareResourceMission(owner=state,scene=mission){if(scene?.id!=='N5'||scene.resourcePrepared||owner.resourcePlanning||!window.worldReady)return;owner.resourcePlanning=true;const origin=currentPosition(),altitude=owner.altitude,active=()=>state===owner&&mission===scene&&owner.status==='review'&&owner.altitude===altitude;render();try{const home=Sequence.points[0].point,surface=window.worldLandingSurface?.({x:home[0],y:home[1],z:altitude});if(!surface||surface.normalY<.97||/树|湖面/.test(surface.label))throw Error('返航降落点不可用');const result=await ResourceMission.prepare({mission:scene,origin:[origin.x,origin.y],home:Sequence.points[0].point,required:scene.resourceTaskRequests?.required||Sequence.points[4].point,optional:scene.resourceTaskRequests?.optional||Sequence.points[1].point,battery:owner.battery,speed:owner.speed,altitude,landingTarget:surface.altitude+Collision.radius+.08,active,plan:(a,b)=>FreeNavigation.plan({origin:a,target:{point:b},bounds:C.workArea,active,clearance:p=>window.worldPointClearance({x:p[0],y:p[1],z:altitude}).distance,collision:(a,b)=>!!window.worldCollision({x:a[0],y:a[1],z:altitude},{x:b[0],y:b[1],z:altitude})})});if(!active())return;owner.route=C.clone(result.route);owner.progress=0;owner.battery=result.battery;owner.resourceCompleted=[];scene.resourceDecisionTime=owner.simTime;scene.summary='资源满足计划，先执行P4、P5并返回A；飞行中更新可用电量。';owner.resourcePlanning=false;if(owner.taskStarted)owner.status='running';log('resource_plan','生成必需与可选任务返航路线',JSON.stringify(scene.resourceEnergy));}catch(error){if(state===owner&&mission===scene)scene.resourcePlanError=error.message}finally{if(state===owner&&mission===scene){owner.resourcePlanning=false;render();window.focusMissionRoute?.([...scene.initialRoute,...owner.route]);}}}
async function raiseResourceEvent(){
 const p=currentPosition(),full=Traffic.remainingRoute(state.route,state.progress),n=C.nearestPointOnRoute(mission.resourceReduced,[p.x,p.y]);let reduced=[[p.x,p.y],...mission.resourceReduced.slice((n?.segmentIndex??0)+1)];const landing=ResourceMission.descent(state.altitude,mission.landingTargetAltitude),fullCost=ResourceMission.cost(full,state.speed)+(landing?.cost||0),reducedCost=ResourceMission.cost(reduced,state.speed)+(landing?.cost||0);
 if(state.modified){const owner=state,scene=mission,alt=state.altitude;state.resourceDetected=true;state.resourcePlanning=true;state.status='paused';render();try{const plan=(a,b)=>FreeNavigation.plan({origin:a,target:{point:b},bounds:C.workArea,active:()=>state===owner&&mission===scene&&state.altitude===alt,clearance:q=>window.worldPointClearance({x:q[0],y:q[1],z:alt}).distance,collision:(a,b)=>!!window.worldCollision({x:a[0],y:a[1],z:alt},{x:b[0],y:b[1],z:alt})});const required=mission.resourceTasks.find(t=>t.priority==='必需'&&!(state.resourceCompleted||[]).includes(t.id));if(required){const first=await plan([p.x,p.y],required.point),back=await plan(first.at(-1),mission.returnPoint);reduced=first.concat(back.slice(1));}else reduced=await plan([p.x,p.y],mission.returnPoint);if(state!==owner||mission!==scene)return;}catch(error){if(state!==owner||mission!==scene)return;mission.resourcePlanError='从当前位置返航规划失败：'+error.message;}finally{if(state===owner&&mission===scene)state.resourcePlanning=false;}}const adjustedCost=ResourceMission.cost(reduced,state.speed)+(landing?.cost||0),timeLimited=Number.isFinite(mission.deadlineSeconds);state.resourceDetected=true;startFlightEvent('resource',timeLimited?'任务截止时刻更新':'电池可用容量更新',timeLimited?'收到任务时限缩短通知':'能量管理系统更新剩余可用容量');const before=state.battery;if(timeLimited)mission.deadlineSeconds=state.simTime+(C.length(full)/state.speed+C.length(reduced)/state.speed)/2+(landing?.seconds||0);else state.battery=Math.min(before,15+(fullCost+adjustedCost)/2);mission.title=timeLimited?'任务时限更新：比较完整与缩减任务':'可用容量更新：比较完整与缩减任务';mission.resourceDecisionTime=state.simTime;mission.resourceEnergy={original:state.battery-fullCost,adjusted:state.battery-adjustedCost,originalSeconds:C.length(full)/state.speed+(landing?.seconds||0),adjustedSeconds:C.length(reduced)/state.speed+(landing?.seconds||0)};mission.initialRoute=C.clone(full);mission.route=reduced;mission.alternative=full;state.route=full;state.progress=0;state.status='review';state.presentedAt=Date.now();readyCandidate(reduced);eventLog('resource_capacity_update',JSON.stringify({before,after:state.battery,fullCost,adjustedCost,deadline:mission.deadlineSeconds}));render();
}
function presentStage(index,resume=false){
 const before=snap(),position=currentPosition(),origin=resume?[position.x,position.y]:Sequence.points[index].point;
 if(index!==3&&Math.hypot(origin[0]-Sequence.points[index+1].point[0],origin[1]-Sequence.points[index+1].point[1])<3){toast('已在当前目标附近，请手动退开后重规划');return}
 const oldSequence=state.sequence||{},oldTraffic=resume?state.traffic:null,oldPhotoIds=resume&&index===0?C.clone(state.photoCheckpointIds||[]):[],oldPhotoEvidence=resume&&index===0?C.clone(state.photoEvidence||[]):[],rate=state.simRate||4;const next=Sequence.make(index,origin,state.battery),oldTime=state.simTime,trail=C.clone(state.trail),altitude=state.altitude,speed=state.speed;
 manualInputs.clear();joystick={forward:0,right:0};session.node=next.id;mission=next;draft=null;
 state={taskStarted:!!state.taskStarted,status:'review',sequence:{index,single:!!oldSequence.single},simRate:rate,route:C.clone(next.route),progress:0,altitude,targetAltitude:altitude,speed,battery:next.battery,simTime:oldTime,goalDeferred:false,trail,presentedAt:Date.now(),photoCheckpointIds:oldPhotoIds,photoEvidence:oldPhotoEvidence,activePhotoCheckpointId:null,noFlyDetected:false,noFlyVisible:false};
 $('destinationPanel').hidden=true;$('toggleMission').setAttribute('aria-expanded','false');$('aiBody').hidden=false;$('toggleAI').textContent='−';$('toggleAI').setAttribute('aria-expanded','true');
 if(index===3){next.resourcePrepared=false;}if(index===2){state.traffic=oldTraffic||Traffic.create(origin,next.destination.point,speed,next.route);$('pitch').value='20';$('pitchValue').textContent='−20°';window.flightView?.pitch?.(20)}$('simRate').value=String(rate);
 if(state.taskStarted&&index!==3&&!resume)state.status='running';state.activePlan='航迹A';log('present',resume?'手动接管后重新规划':'触发连续航线事件',next.event,before);render();if(index===3)prepareResourceMission();window.focusMissionRoute?.([...(state.trail||[]),...state.route,...(!state.sequence.single?Sequence.points.slice(index+1).map(p=>p.point):[])]);
}
$('simRate').value=String(state.simRate||4);if(mission){$('destinationInput').value=mission.destination.name;$('destinationPanel').hidden=true;$('toggleMission').setAttribute('aria-expanded','false')}render();if(state.freeFlight)window.focusMissionRoute?.([[100,300],[700,800]]);if(mission)window.focusMissionRoute?.([...(state.trail||[]),...state.route]);if(mission?.id==='N4'&&state.conflictAlert&&state.traffic){const target=Traffic.position(state.traffic);window.focusMissionRoute?.([...mission.initialRoute,...state.route,[target.x,target.y]])}requestAnimationFrame(tick);





